// <auto-generated-scaffold>
//   HAND-WRITTEN. Development-only stock ON THE FAR SIDE, so the app has to fetch it.
// </auto-generated-scaffold>
#nullable enable

using StockFeed.Contracts;   // StockNoticed — the model-declared foreign event

namespace StockFeed.Landing;

/// <summary>
/// What the warehouse already knows when we start up, for running the app by hand. The counterpart of
/// GenesisData, and it lives here rather than there because these are not our events — see GenesisData for why
/// that distinction matters more on this pattern than on any other.
/// </summary>
public static class WarehouseDemoData
{
    public static readonly Guid Widget = Guid.Parse("aaaaaaaa-0000-0000-0000-000000000001");
    public static readonly Guid Sprocket = Guid.Parse("aaaaaaaa-0000-0000-0000-000000000002");
    public static readonly Guid Flange = Guid.Parse("aaaaaaaa-0000-0000-0000-000000000003");

    private static Guid Notice(int n) => Guid.Parse($"bbbbbbbb-0000-0000-0000-{n:D12}");

    public static void Stock(InMemoryWarehouseFeed warehouse)
    {
        var at = new DateTimeOffset(2026, 1, 1, 9, 0, 0, TimeSpan.Zero);

        warehouse.Publish(new StockNoticed(Widget, Notice(1), 42, 1, at));
        warehouse.Publish(new StockNoticed(Sprocket, Notice(2), 7, 2, at.AddMinutes(1)));
        warehouse.Publish(new StockNoticed(Flange, Notice(3), 0, 3, at.AddMinutes(2)));

        // A SECOND NOTICE FOR ONE PRODUCT, later and with a higher sequence. Here so that running the app shows
        // the behaviour worth seeing rather than only the happy path: the todo View collapses both notices to
        // one outstanding row, and the Widget settles at 40 rather than 42.
        warehouse.Publish(new StockNoticed(Widget, Notice(4), 40, 4, at.AddMinutes(3)));

        // THERE IS NO STALE NOTICE HERE, AND TRYING TO ADD ONE IS HOW A REAL FINDING TURNED UP.
        //
        // A stale notice needs a sequence LOWER than one already accepted. But this same field is the poll
        // clock's high-water mark — it asks the warehouse for "everything after N" — so a notice with a lower
        // sequence is one the poll will never fetch, by construction. Which is not a limitation of the demo
        // data: it is the truth about the mechanism.
        //
        // A CURSOR-ORDERED PULL FEED CANNOT DELIVER OUT OF ORDER. Reading in cursor order is what makes it a
        // cursor. So the StaleNotice rule guards against a hazard that only SOME landing mechanisms have —
        // a webhook can arrive in any order, a queue can redeliver, a poll cannot — and you cannot know
        // whether you need it without knowing how the notice lands. The rule stays regardless, because the
        // landing mechanism is a choice somebody may change later and the rule is what makes that choice
        // safe to change.
        //
        // To watch a refusal, run with Feed:Landing=webhook and POST a notice with a low sequence by hand.
    }
}
